import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './CSS/SellerDashboard.css'; // Ensures it loads your dashboard theme stylesheet

export default function AddProductPage() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    brand: '',
    category: 'Electronics',
    price: '',
    mrp: '',
    stock: '',
    description: '',
    features: ''
  });
  const [selectedImages, setSelectedImages] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleImageChange = (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 10) {
      alert("You can upload a maximum of 10 images.");
      return;
    }
    setSelectedImages(files);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const data = new FormData();
    data.append('title', formData.title);
    data.append('brand', formData.brand);
    data.append('category', formData.category);
    data.append('price', formData.price);
    data.append('mrp', formData.mrp);
    data.append('stock', formData.stock);
    data.append('description', formData.description);
    
    const featureArray = formData.features.split('\n').filter(f => f.trim() !== '');
    featureArray.forEach(feature => data.append('features', feature));

    selectedImages.forEach(file => {
      data.append('images', file);
    });

    try {
      await axios.post('http://localhost:4000/api/seller/products', data, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      alert('Product published successfully!');
      navigate('/seller');
    } catch (err) {
      console.error(err);
      alert('Failed to publish product');
    } finally {
      setLoading(false);
    }
  };

  return (
    /* Use your exact dashboard container class name here so it inherits your portal theme */
    <div className="seller-dashboard-container" style={{ padding: '30px', width: '100%', boxSizing: 'border-box' }}>
      <div className="dashboard-content-card" style={{ background: '#fff', borderRadius: '8px', padding: '30px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
        
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', borderBottom: '1px solid #e2e8f0', paddingBottom: '15px' }}>
          <div>
            <h2 style={{ margin: 0, color: '#1e293b' }}>Add New Product (Amazon Style)</h2>
            <p style={{ margin: '5px 0 0 0', color: '#64748b', fontSize: '14px' }}>Fill in the details below to list your item on Hexstore.</p>
          </div>
          <button type="button" onClick={() => navigate('/seller')} className="btn-secondary" style={{ padding: '8px 16px', cursor: 'pointer', borderRadius: '4px', border: '1px solid #cbd5e1', background: '#f1f5f9' }}>
            ← Back to Dashboard
          </button>
        </div>

        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          
          <div>
            <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>Product Title *</label>
            <input type="text" name="title" value={formData.title} onChange={handleChange} required style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #cbd5e1' }} />
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
            <div>
              <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>Brand / Store Name</label>
              <input type="text" name="brand" value={formData.brand} onChange={handleChange} style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #cbd5e1' }} />
            </div>
            <div>
              <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>Category *</label>
              <select name="category" value={formData.category} onChange={handleChange} style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #cbd5e1', background: '#fff' }}>
                <option value="Electronics">Electronics</option>
                <option value="Smart phones">Smart phones</option>
                <option value="Smart watches">Smart watches</option>
                <option value="Home & Kitchen">Home & Kitchen</option>
                <option value="Fashion">Fashion</option>
              </select>
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px' }}>
            <div>
              <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>Selling Price *</label>
              <input type="number" name="price" value={formData.price} onChange={handleChange} required style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #cbd5e1' }} />
            </div>
            <div>
              <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>M.R.P</label>
              <input type="number" name="mrp" value={formData.mrp} onChange={handleChange} style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #cbd5e1' }} />
            </div>
            <div>
              <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>Available Stock *</label>
              <input type="number" name="stock" value={formData.stock} onChange={handleChange} required style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #cbd5e1' }} />
            </div>
          </div>

          <div>
            <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>Product Description</label>
            <textarea name="description" rows="4" value={formData.description} onChange={handleChange} placeholder="Detailed overview..." style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #cbd5e1' }} />
          </div>

          <div>
            <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>Key Features / Bullet Points (Each line becomes a bullet)</label>
            <textarea name="features" rows="4" value={formData.features} onChange={handleChange} placeholder="e.g. Rechargeable 2W Led Torch&#10;Metallic Finish" style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #cbd5e1' }} />
          </div>

          <div style={{ background: '#f8fafc', padding: '15px', borderRadius: '6px', border: '1px dashed #cbd5e1' }}>
            <label style={{ display: 'block', fontWeight: '600', marginBottom: '6px', color: '#334155' }}>Product Images (Select up to 10 images)</label>
            <input type="file" name="images" multiple accept="image/*" onChange={handleImageChange} style={{ display: 'block', marginTop: '5px' }} />
            <small style={{ color: '#64748b', marginTop: '5px', display: 'block' }}>✓ {selectedImages.length} image(s) selected (Max 10)</small>
          </div>

          <div style={{ display: 'flex', gap: '15px', justifyContent: 'flex-end', marginTop: '10px' }}>
            <button type="button" onClick={() => navigate('/seller')} style={{ padding: '10px 20px', background: '#e2e8f0', color: '#334155', fontWeight: '600', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>Cancel</button>
            <button type="submit" disabled={loading} style={{ padding: '10px 24px', background: '#FF9900', color: '#000000', fontWeight: 'bold', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
              {loading ? 'Publishing...' : 'Save and Publish Product'}
            </button>
          </div>

        </form>
      </div>
    </div>
  );
}
